changeSet.sql:
ALTER TABLE exercise ADD COLUMN id UUID;
UPDATE exercise SET id = gen_random_uuid() WHERE id IS NULL;
ALTER TABLE exercise ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE exercise ALTER COLUMN id SET NOT NULL;

ALTER TABLE session ADD COLUMN id UUID;
UPDATE session SET id = gen_random_uuid() WHERE id IS NULL;
ALTER TABLE session ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE session ALTER COLUMN id SET NOT NULL;

ALTER TABLE performed_exercise ADD COLUMN id UUID;
UPDATE performed_exercise SET id = gen_random_uuid() WHERE id IS NULL;
ALTER TABLE performed_exercise ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE performed_exercise ALTER COLUMN id SET NOT NULL;

ALTER TABLE performed_exercise ADD COLUMN session_id UUID;
ALTER TABLE performed_exercise ADD COLUMN exercise_id UUID;

UPDATE performed_exercise pe
SET session_id = s.id
FROM session s
WHERE pe.session_ssid = s.ssid;

UPDATE performed_exercise pe
SET exercise_id = e.id
FROM exercise e
WHERE pe.exercise_eid = e.eid;

ALTER TABLE performed_exercise ALTER COLUMN session_id SET NOT NULL;
ALTER TABLE performed_exercise ALTER COLUMN exercise_id SET NOT NULL;

ALTER TABLE performed_set ADD COLUMN id UUID;
UPDATE performed_set SET id = gen_random_uuid() WHERE id IS NULL;
ALTER TABLE performed_set ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE performed_set ALTER COLUMN id SET NOT NULL;

ALTER TABLE performed_set ADD COLUMN performed_exercise_id UUID;

UPDATE performed_set ps
SET performed_exercise_id = pe.id
FROM performed_exercise pe
WHERE ps.performed_exercise_peid = pe.peid;

ALTER TABLE performed_set ALTER COLUMN performed_exercise_id SET NOT NULL;

